# Generates src/julia_lsp_vocab.cpp: the names mep-julia-lsp knows without
# reading any package -- Core's and Base's exported (and `public`) names and
# those of the standard library modules a file can `using` -- with their
# kind, signatures and docstrings, taken from the running Julia.
#
# Julia and its standard library are MIT-licensed, so the docstrings are
# embedded with the notice (the header of the generated file).
#
# Usage: julia --startup-file=no tools/gen_julia_vocab.jl > src/julia_lsp_vocab.cpp
#        (`just julia-vocab`)

const STDLIBS = [:LinearAlgebra, :Statistics, :Random, :Printf, :Dates, :Test, :SparseArrays,
                 :Serialization, :Distributed, :InteractiveUtils, :Markdown, :Sockets, :Logging,
                 :Unicode, :UUIDs, :Base64, :Mmap, :TOML, :SharedArrays, :Profile, :FileWatching,
                 :Libdl, :DelimitedFiles, :Downloads, :Pkg, :REPL, :Tar, :LibGit2, :CRC32c, :Sockets,
                 :StyledStrings, :Future]

const MAX_DOC = 4000

loaded = Module[Core, Base]
for s in unique(STDLIBS)
    try
        Core.eval(Main, :(using $s))
        push!(loaded, Base.invokelatest(getfield, Main, s))
    catch err
        @warn "skipping $s" err
    end
end

function rawdocs(mod::Module, sym::Symbol)
    b = Base.Docs.Binding(mod, sym)
    for m in unique([b.mod, mod])
        meta = Base.Docs.meta(m)
        haskey(meta, b) || continue
        md = meta[b]
        return [join(string.(md.docs[sig].text)) for sig in md.order]
    end
    # An alias (`Int`, `Float`) documents nothing itself: its target's docs.
    if isdefined(mod, sym)
        v = getfield(mod, sym)
        if v isa DataType && (parentmodule(v), nameof(v)) != (mod, sym)
            return rawdocs(parentmodule(v), nameof(v))
        end
    end
    return String[]
end

function kindof(mod::Module, sym::Symbol)
    isdefined(mod, sym) || return "constant"
    v = getfield(mod, sym)
    v isa Module && return "module"
    (v isa Type || v isa TypeVar) && return "type"
    startswith(string(sym), "@") && return "macro"
    v isa Function && return "function"
    return "constant"
end

# The signatures a docstring opens with: its leading indented lines.
function signatures(docs)
    sigs = String[]
    for d in docs
        for line in split(d, '\n')
            startswith(line, "    ") || break
            s = strip(line)
            isempty(s) || push!(sigs, s)
        end
    end
    unique(sigs)
end

function cstr(s::AbstractString)
    io = IOBuffer()
    print(io, '"')
    for c in s
        if c == '\\'
            print(io, "\\\\")
        elseif c == '"'
            print(io, "\\\"")
        elseif c == '\n'
            print(io, "\\n")
        elseif c == '\t'
            print(io, "\\t")
        elseif c == '?'
            print(io, "\\?")   # no trigraphs
        elseif c < ' ' || c == '\x7f'
            print(io, "\\", string(UInt8(c), base=8, pad=3))
        elseif !isvalid(c)
            print(io, "\\ufffd")
        else
            print(io, c)
        end
    end
    print(io, '"')
    String(take!(io))
end

rows = Tuple{String,String,String,String,String}[]
seen = Set{Tuple{String,String}}()
for mod in loaded
    modname = string(nameof(mod))
    for sym in sort(names(mod))
        str = string(sym)
        (str == modname || occursin('#', str)) && continue
        key = (modname, str)
        key in seen && continue
        push!(seen, key)
        docs = rawdocs(mod, sym)
        sigs = signatures(docs)
        doc = isempty(docs) ? "" : strip(join(docs, "\n\n---\n\n"))
        if length(doc) > MAX_DOC
            doc = first(doc, MAX_DOC) * "\n\n..."
        end
        push!(rows, (modname, str, kindof(mod, sym), join(sigs, "\n"), doc))
    end
end
sort!(rows, by = r -> (r[2], r[1]))

println("// Generated by tools/gen_julia_vocab.jl from Julia ", VERSION, " -- do not edit.")
println("// Docstrings from Julia and its standard library: Copyright (c) 2009-2025: Jeff Bezanson,")
println("// Stefan Karpinski, Viral B. Shah, and other contributors: https://github.com/JuliaLang/julia/contributors")
println("// Licensed under the MIT license (\"Expat\").")
println("#include \"julia_lsp_vocab.h\"")
println()
println("namespace {")
println()
println("const JuliaLspApi kApi[] = {")
for (m, n, k, s, d) in rows
    println("    {", cstr(m), ", ", cstr(n), ", ", cstr(k), ", ", cstr(s), ", ", cstr(d), "},")
end
println("};")
println()
println("}  // namespace")
println()
println("const JuliaLspApi *JuliaLspApiTable(size_t *count) {")
println("    *count = sizeof(kApi) / sizeof(kApi[0]);")
println("    return kApi;")
println("}")
